// ===== Freigabe vor Zahlung · Modul 4 · Nyxaris · Stand 11.11.2026 =====
// Jede abgelegte Rechnung braucht eine Freigabe durch die zuständige Person, bevor sie als „zahlbar“ gilt.
// Ablauf: Rechnung liegt im Standortordner → Status „zur Freigabe“ → Link → Bestätigungsseite → Freigeben/Zurückweisen.
// Angehaltene Rechnungen (Ordner _angehalten) können erst freigegeben werden, wenn die Bankverbindung geklärt
// und die Datei zurück in den Standortordner geschoben ist. Kein Bankzugang, keine Zahlung durch den Ablauf.
const fs = require('fs'); const path = require('path');
const KONFIG = {
  basis: '/data/buchhaltung',
  protokoll: '/data/buchhaltung/_protokoll',
  seite: '/data/buchhaltung/_freigabe',            // Übersichtsseite und Liste „zahlbar“
  linkBasis: 'http://localhost:5678/webhook/BITTE-EIGENEN-PFAD-EINSETZEN',  // ANPASSEN beim Kunden (nur im eigenen Netz/VPN erreichbar)
  erinnerungNachTagen: 3,                          // Erinnerung, wenn eine Rechnung so lange liegt
  zustaendig: {                                    // ANPASSEN: Standortordner → zuständige Person
    '1 Musterbetrieb Hauptsitz': { name: 'Geschäftsführung (Muster)', mail: 'gf@example.de' },
    '2 Musterbetrieb Filiale': { name: 'Filialleitung (Muster)', mail: 'filiale@example.de' },
  },
  endungen: /\.(pdf|xml)$/i,
};
const speicher = path.join(KONFIG.protokoll, 'freigaben.json');
const jetzt = $now.setZone('Europe/Berlin');
const zeit = () => jetzt.toFormat('yyyy-MM-dd HH:mm:ss');
const esc = s => String(s == null ? '' : s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
const eur = n => n == null ? '–' : Number(n).toLocaleString('de-DE', { minimumFractionDigits: 2, maximumFractionDigits: 2 }) + ' €';
function laden() { try { return JSON.parse(fs.readFileSync(speicher, 'utf8')); } catch (e) { return { rechnungen: {} }; } }
function sichern(d) { fs.mkdirSync(KONFIG.protokoll, { recursive: true }); const t = speicher + '.tmp'; fs.writeFileSync(t, JSON.stringify(d, null, 1)); fs.renameSync(t, speicher); }
function protokoll(e, vorgang) {
  const f = path.join(KONFIG.protokoll, 'freigaben-' + jetzt.toFormat('yyyy-MM') + '.csv');
  if (!fs.existsSync(f)) fs.writeFileSync(f, '﻿Zeitpunkt;Vorgang;Standort;Datei;Lieferant;Rechnungsnr;Brutto;Durch;Grund\n');
  const z = [zeit(), vorgang, e.standort, e.datei, e.lieferant, e.nr, e.brutto == null ? '' : Number(e.brutto).toFixed(2).replace('.', ','), e.durch || '', e.grund || ''];
  fs.appendFileSync(f, z.map(s => String(s == null ? '' : s).replace(/[;\r\n]+/g, ' ')).join(';') + '\n');
}
const STATUS = { offen: 'zur Freigabe', angehalten: 'angehalten', freigegeben: 'freigegeben – zahlbar', zurueckgewiesen: 'zurückgewiesen', fehlt: 'Datei nicht mehr vorhanden' };
function seiteBauen(d) {
  const alle = Object.values(d.rechnungen).sort((a, b) => String(b.angelegt).localeCompare(String(a.angelegt)));
  const zeile = (e, mitLink) => `<tr><td>${esc(e.standort)}</td><td>${esc(e.lieferant || '–')}<br><small>${esc(e.datei)}</small>${e.hinweise ? `<br><small style="color:#8A6A12">⚠ ${esc(e.hinweise)}</small>` : ''}</td><td>${esc(e.nr || '–')}</td><td style="text-align:right">${eur(e.brutto)}${e.brutto != null && e.quelle === 'Text' ? '<br><small>aus PDF gelesen</small>' : ''}</td><td>${mitLink ? `<a class="b" href="${esc(KONFIG.linkBasis)}?t=${e.token}">Prüfen und entscheiden</a>` : esc(STATUS[e.status] || e.status) + (e.entschieden ? `<br><small>${esc(e.durch || '')} · ${esc(e.entschieden)}${e.grund ? ' · ' + esc(e.grund) : ''}</small>` : '') + (e.status === 'angehalten' ? `<br><small>${esc(e.stoppGrund || '')}</small>` : '')}</td></tr>`;
  const tab = (titel, liste, mitLink, leer) => `<h2>${titel} <span>${liste.length}</span></h2>` + (liste.length ? `<table><tr><th>Standort</th><th>Lieferant / Datei</th><th>Rechnungsnr.</th><th style="text-align:right">Brutto</th><th>${mitLink ? 'Aktion' : 'Status'}</th></tr>${liste.map(e => zeile(e, mitLink)).join('')}</table>` : `<p class="m">${leer}</p>`);
  const html = `<!doctype html><html lang="de"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Freigabe vor Zahlung</title><style>
body{font-family:Inter,Arial,sans-serif;color:#26303F;margin:0;background:#F3F6FA}.k{background:#0B1527;color:#fff;padding:20px 28px}.k b{letter-spacing:.3em}.k b i{font-style:normal;color:#0E8C81}.k h1{margin:6px 0 0;font-size:22px}.k p{color:#C3CDDB;margin:4px 0 0;font-size:13px}
main{max-width:980px;margin:0 auto;padding:10px 20px 40px}h2{font-size:13px;letter-spacing:.12em;text-transform:uppercase;border-bottom:2px solid #0E8C81;padding-bottom:4px;margin-top:28px}h2 span{color:#6B7A90}
table{width:100%;border-collapse:collapse;background:#fff;font-size:14px}th,td{padding:8px 10px;border-bottom:1px solid #DFE5EE;text-align:left;vertical-align:top}th{font-size:11px;color:#6B7A90;text-transform:uppercase;letter-spacing:.05em}small{color:#6B7A90}
a.b{display:inline-block;background:#0E8C81;color:#fff;text-decoration:none;padding:6px 12px;border-radius:999px;font-weight:600;font-size:13px}.m{color:#6B7A90}.h{background:#FDF6F4;border-left:3px solid #A4341F;padding:10px 14px;font-size:14px}</style></head><body>
<div class="k"><b>NYXAR<i>I</i>S</b><h1>Freigabe vor Zahlung</h1><p>Stand ${esc(jetzt.toFormat('dd.MM.yyyy HH:mm'))} · Bezahlt wird nur, was hier freigegeben ist.</p></div><main>
${tab('Zur Freigabe', alle.filter(e => e.status === 'offen'), true, 'Nichts offen.')}
${tab('Angehalten – erst Bankverbindung klären', alle.filter(e => e.status === 'angehalten'), false, 'Keine angehaltene Rechnung.')}
${alle.some(e => e.status === 'angehalten') ? '<p class="h">Lieferanten unter der <b>bekannten</b> Telefonnummer anrufen. Stimmt alles, die Datei aus „_angehalten“ zurück in den Standortordner schieben – beim nächsten Abgleich erscheint sie oben zur Freigabe.</p>' : ''}
${tab('Entschieden', alle.filter(e => e.status === 'freigegeben' || e.status === 'zurueckgewiesen'), false, 'Noch nichts entschieden.')}
<p class="m" style="font-size:12px;margin-top:28px">Automatisch erstellt. Der Ablauf hat keinen Bankzugang und löst keine Zahlung aus. Keine Steuer- oder Buchhaltungsberatung.</p></main></body></html>`;
  fs.mkdirSync(KONFIG.seite, { recursive: true });
