  fs.writeFileSync(path.join(KONFIG.seite, 'zahlbar.csv'), '﻿Freigegeben;Durch;Standort;Lieferant;Rechnungsnr;Brutto;Datei\n' +
    zahlbar.map(e => [e.entschieden, e.durch, e.standort, e.lieferant, e.nr, e.brutto == null ? '' : Number(e.brutto).toFixed(2).replace('.', ','), e.datei].map(s => String(s == null ? '' : s).replace(/[;\r\n]+/g, ' ')).join(';')).join('\n') + '\n');
}

// ===== Abgleich: Ordner lesen, neue Rechnungen zur Freigabe stellen, Erinnerungen, Seite neu bauen =====
function token() {
  try { return require('crypto').randomBytes(16).toString('hex'); } catch (e) {}
  if (globalThis.crypto && globalThis.crypto.getRandomValues) { const a = new Uint8Array(16); globalThis.crypto.getRandomValues(a); return Array.from(a, b => b.toString(16).padStart(2, '0')).join(''); }
  throw new Error('Kein sicherer Zufall verfügbar – in docker-compose NODE_FUNCTION_ALLOW_BUILTIN um crypto ergänzen');
}
function csv(datei) {
  if (!fs.existsSync(datei)) return [];
  const z = fs.readFileSync(datei, 'utf8').replace(/^﻿/, '').split(/\r?\n/).filter(Boolean);
  const kopf = z.shift().split(';');
  return z.map(l => { const f = l.split(';'); const o = {}; kopf.forEach((k, i) => o[k] = f[i] || ''); return o; });
}
// Angaben zur Rechnung aus dem Prüfprotokoll des Belegeingangs (letzter Eintrag je Datei)
const angaben = {};
for (const f of (fs.existsSync(KONFIG.protokoll) ? fs.readdirSync(KONFIG.protokoll) : []).filter(f => /^pruefung-\d{4}-\d{2}\.csv$/.test(f)).sort())
  for (const p of csv(path.join(KONFIG.protokoll, f))) if (p.Datei) angaben[p.Datei] = p;
const namen = {};
try { const g = JSON.parse(fs.readFileSync(path.join(KONFIG.protokoll, 'lieferanten-gedaechtnis.json'), 'utf8'));
  for (const l of Object.values(g.lieferanten || {})) for (const dm of (l.domains || [])) if (l.name) namen[dm.toLowerCase()] = l.name; } catch (e) {}
for (const a of Object.values(angaben)) a.Lieferant = namen[String(a.Lieferant || '').toLowerCase()] || a.Lieferant;
const zahl = s => { const n = Number(String(s || '').replace(/\./g, '').replace(',', '.')); return s && Number.isFinite(n) ? n : null; };

const d = laden();
const gesehen = new Set();
const neu = [], erinnerungen = [];
for (const standort of Object.keys(KONFIG.zustaendig)) {
  const dir = path.join(KONFIG.basis, standort);
  for (const [ort, ordner] of [['standort', dir], ['angehalten', path.join(dir, '_angehalten')]]) {
    if (!fs.existsSync(ordner)) continue;
    for (const datei of fs.readdirSync(ordner)) {
      const p = path.join(ordner, datei);
      if (!KONFIG.endungen.test(datei) || !fs.statSync(p).isFile()) continue;
      const key = standort + '/' + datei; gesehen.add(key);
      const mtime = Math.round(fs.statSync(p).mtimeMs);
      const a = angaben[datei] || {};
      let e = d.rechnungen[key];
      if (e && e.mtime !== mtime && Math.abs(e.mtime - mtime) > 2000 && (e.status === 'freigegeben' || e.status === 'zurueckgewiesen')) e = null;   // neue Datei unter gleichem Namen
      if (!e) {
        e = d.rechnungen[key] = { token: token(), standort, datei, mtime, angelegt: zeit(), status: ort === 'angehalten' ? 'angehalten' : 'offen' };
        neu.push(e); protokoll(Object.assign(e, { lieferant: a.Lieferant, nr: a.Rechnungsnr, brutto: zahl(a.Brutto) }), e.status === 'offen' ? 'zur Freigabe gestellt' : 'angehalten erfasst');
      } else if (e.status === 'angehalten' && ort === 'standort') {
        e.status = 'offen'; e.angelegt = zeit(); e.erinnert = null; protokoll(e, 'aus _angehalten zurück – zur Freigabe gestellt');
      } else if (e.status === 'offen' && ort === 'angehalten') {
        e.status = 'angehalten'; protokoll(e, 'nach _angehalten verschoben');
      } else if (e.status === 'fehlt') { e.status = ort === 'angehalten' ? 'angehalten' : 'offen'; }
      e.mtime = mtime; e.ort = ort;
      e.lieferant = a.Lieferant || e.lieferant || ''; e.nr = a.Rechnungsnr || e.nr || ''; e.brutto = zahl(a.Brutto) != null ? zahl(a.Brutto) : (e.brutto != null ? e.brutto : null);
      e.stoppGrund = a.Gruende || e.stoppGrund || '';
      e.quelle = a.Quelle || e.quelle || '';
      e.hinweise = (a.Hinweise || e.hinweise || '').replace(/ \| /g, '; ');
      const z = KONFIG.zustaendig[standort] || {}; e.zustaendig = z.name || ''; e.mail = z.mail || '';
    }
  }
}
for (const [key, e] of Object.entries(d.rechnungen)) if (!gesehen.has(key) && (e.status === 'offen' || e.status === 'angehalten')) { e.status = 'fehlt'; protokoll(e, 'Datei nicht mehr vorhanden'); }
// Erinnerungen: offen seit X Tagen, höchstens alle X Tage
const tage = ts => ts ? (Date.now() - Date.parse(String(ts).replace(' ', 'T'))) / 86400000 : Infinity;
for (const e of Object.values(d.rechnungen)) {
  if (e.status !== 'offen' || tage(e.angelegt) < KONFIG.erinnerungNachTagen) continue;
  if (e.erinnert && tage(e.erinnert) < KONFIG.erinnerungNachTagen) continue;
  e.erinnert = zeit(); erinnerungen.push(e); protokoll(e, 'Erinnerung');
}
sichern(d); seiteBauen(d);
const anzahl = s => Object.values(d.rechnungen).filter(e => e.status === s).length;
// Mails (im Labor deaktiviert): je zuständige Person eine Nachricht mit ihren offenen Rechnungen
const jePerson = {};
for (const e of [...neu.filter(e => e.status === 'offen'), ...erinnerungen]) (jePerson[e.mail] = jePerson[e.mail] || { an: e.mail, name: e.zustaendig, liste: [] }).liste.push(e);
const mails = Object.values(jePerson).filter(p => p.an).map(p => ({ json: {
  an: p.an,
  betreff: `Freigabe vor Zahlung: ${p.liste.length} Rechnung(en) warten auf Sie`,
  text: `Guten Tag,\n\nfolgende Rechnungen warten auf Ihre Freigabe:\n\n${p.liste.map(e => `- ${e.lieferant || e.datei}${e.nr ? ' · ' + e.nr : ''}${e.brutto != null ? ' · ' + eur(e.brutto) : ''}\n  ${KONFIG.linkBasis}?t=${e.token}`).join('\n')}\n\nDer Link öffnet eine Bestätigungsseite – erst dort wird entschieden.\n\nDiese Nachricht wurde automatisch erzeugt.`,
} }));
return [{ json: { zurFreigabe: anzahl('offen'), angehalten: anzahl('angehalten'), freigegeben: anzahl('freigegeben'), zurueckgewiesen: anzahl('zurueckgewiesen'), neu: neu.length, erinnerungen: erinnerungen.length, seite: path.join(KONFIG.seite, 'Freigaben.html'), mails: mails.map(m => m.json) } }];

